ALTER TABLE "storefront"."configuration" ADD COLUMN "brand_icon_asset_id" uuid;--> statement-breakpoint
ALTER TABLE "storefront"."configuration" ADD CONSTRAINT "configuration_brand_icon_asset_id_brand_asset_id_fk" FOREIGN KEY ("brand_icon_asset_id") REFERENCES "storefront"."brand_asset"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "storefront"."brand_asset" ADD CONSTRAINT "brand_asset_kind_check" CHECK ("storefront"."brand_asset"."kind" in ('logo', 'brandIcon', 'favicon', 'socialImage'));--> statement-breakpoint
ALTER TABLE "storefront"."brand_asset" ADD CONSTRAINT "brand_asset_kind_content_type_check" CHECK (("storefront"."brand_asset"."kind" = 'logo' and "storefront"."brand_asset"."content_type" = 'image/webp') or ("storefront"."brand_asset"."kind" in ('brandIcon', 'favicon') and "storefront"."brand_asset"."content_type" = 'image/png') or ("storefront"."brand_asset"."kind" = 'socialImage' and "storefront"."brand_asset"."content_type" = 'image/jpeg'));--> statement-breakpoint
ALTER TABLE "storefront"."brand_asset" ADD CONSTRAINT "brand_asset_object_key_check" CHECK ("storefront"."brand_asset"."object_key" ~ '^published/storefront/(logo|brandIcon|favicon|socialImage)/[0-9a-f-]{36}/[0-9a-f]{64}\.(webp|png|jpg)$');--> statement-breakpoint
ALTER TABLE "storefront"."brand_asset" ADD CONSTRAINT "brand_asset_dimensions_check" CHECK (("storefront"."brand_asset"."kind" = 'logo' and "storefront"."brand_asset"."width" between 1 and 1200 and "storefront"."brand_asset"."height" between 1 and 400) or ("storefront"."brand_asset"."kind" = 'brandIcon' and "storefront"."brand_asset"."width" = 1024 and "storefront"."brand_asset"."height" = 1024) or ("storefront"."brand_asset"."kind" = 'favicon' and "storefront"."brand_asset"."width" = 64 and "storefront"."brand_asset"."height" = 64) or ("storefront"."brand_asset"."kind" = 'socialImage' and "storefront"."brand_asset"."width" = 1200 and "storefront"."brand_asset"."height" = 630));